window.ScripturaLexicons.BDAG_PART_0283 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-01\" data-source=\"BDAG\" data-search=\"περιοικέω verbo habitar nas proximidades; ser vizinho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιοικέω</td><td>verbo</td><td>habitar nas proximidades; ser vizinho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-02\" data-source=\"BDAG\" data-search=\"περίοικος, ον adjetivo; substantivo vizinho; morador das redondezas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περίοικος, ον</td><td>adjetivo; substantivo</td><td>vizinho; morador das redondezas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-03\" data-source=\"BDAG\" data-search=\"περιούσιος, ον adjetivo especialmente escolhido; peculiar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιούσιος, ον</td><td>adjetivo</td><td>especialmente escolhido; peculiar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-04\" data-source=\"BDAG\" data-search=\"περιοχή, ῆς, ἡ substantivo feminino conteúdo ou passagem de um escrito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιοχή, ῆς, ἡ</td><td>substantivo feminino</td><td>conteúdo ou passagem de um escrito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-05\" data-source=\"BDAG\" data-search=\"περιπατέω verbo andar; caminhar; conduzir a vida; comportar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιπατέω</td><td>verbo</td><td>andar; caminhar; conduzir a vida; comportar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-06\" data-source=\"BDAG\" data-search=\"περιπείρω verbo traspassar; empalar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιπείρω</td><td>verbo</td><td>traspassar; empalar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-07\" data-source=\"BDAG\" data-search=\"περίπικρος, ον adjetivo muito amargo; acerbo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περίπικρος, ον</td><td>adjetivo</td><td>muito amargo; acerbo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-08\" data-source=\"BDAG\" data-search=\"περιπίπτω verbo colidir; cair em; deparar-se com BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιπίπτω</td><td>verbo</td><td>colidir; cair em; deparar-se com</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-09\" data-source=\"BDAG\" data-search=\"περιπλέκω verbo entrelaçar ao redor; abraçar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιπλέκω</td><td>verbo</td><td>entrelaçar ao redor; abraçar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-10\" data-source=\"BDAG\" data-search=\"περιποιέω verbo preservar; adquirir; proporcionar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιποιέω</td><td>verbo</td><td>preservar; adquirir; proporcionar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-11\" data-source=\"BDAG\" data-search=\"περιποίησις, εως, ἡ substantivo feminino preservação; aquisição; posse BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιποίησις, εως, ἡ</td><td>substantivo feminino</td><td>preservação; aquisição; posse</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-12\" data-source=\"BDAG\" data-search=\"περίπτωσις, εως, ἡ substantivo feminino desgraça; calamidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περίπτωσις, εως, ἡ</td><td>substantivo feminino</td><td>desgraça; calamidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-13\" data-source=\"BDAG\" data-search=\"περι(ρ)ραίνω verbo aspergir por todos os lados BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περι(ρ)ραίνω</td><td>verbo</td><td>aspergir por todos os lados</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-14\" data-source=\"BDAG\" data-search=\"περι(ρ)ρήγνυμι verbo arrancar rasgando ao redor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περι(ρ)ρήγνυμι</td><td>verbo</td><td>arrancar rasgando ao redor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-15\" data-source=\"BDAG\" data-search=\"περισπάω verbo arrastar para longe; distrair; sobrecarregar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περισπάω</td><td>verbo</td><td>arrastar para longe; distrair; sobrecarregar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-16\" data-source=\"BDAG\" data-search=\"περισσεία, ας, ἡ substantivo feminino superávit; abundância BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περισσεία, ας, ἡ</td><td>substantivo feminino</td><td>superávit; abundância</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-17\" data-source=\"BDAG\" data-search=\"περίσσευμα, ατος, τό substantivo neutro abundância; sobra; resto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περίσσευμα, ατος, τό</td><td>substantivo neutro</td><td>abundância; sobra; resto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-18\" data-source=\"BDAG\" data-search=\"περισσεύω verbo sobrar; abundar; exceder; fazer abundar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περισσεύω</td><td>verbo</td><td>sobrar; abundar; exceder; fazer abundar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-19\" data-source=\"BDAG\" data-search=\"περισσός, ή, όν adjetivo extraordinário; abundante; supérfluo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περισσός, ή, όν</td><td>adjetivo</td><td>extraordinário; abundante; supérfluo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0283-20\" data-source=\"BDAG\" data-search=\"περισσότερος, τέρα, ον adjetivo comparativo maior; mais; ainda mais BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περισσότερος, τέρα, ον</td><td>adjetivo comparativo</td><td>maior; mais; ainda mais</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0283-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιοικέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιοικέω</span>, morar perto e ao redor, estar na vizinhança de, com acusativo de pessoa (Hdt. 5, 78; Aristoph., Equ. 853; Jos., Bell. 1, 63): <span class=\"greek\">οἱ</span> <span class=\"greek\">περιοικοῦντες</span> <span class=\"greek\">αὐτούς</span> «seus vizinhos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.65\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:65</a>.—Renehan ’82, 116.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περίοικος, ον</h1><div class=\"entry-meta\"><span>adjetivo; substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περίοικος</span>, <span class=\"greek\">ον</span>, relativo a morar nas proximidades de outras pessoas, habitante dos arredores, residente na vizinhança; substantivado, no plural, <span class=\"greek\">οἱ</span> <span class=\"greek\">περίοικοι</span> «os vizinhos» (Hdt. 1, 175; 4, 161; Thu. 1, 101, 2; Jos., Vi. 78, Ant. 16, 272; Dt 1:7 em vários sentidos) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.58\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:58</a> (com <span class=\"greek\">συγγενεῖς</span>).—DELG s.v. <span class=\"greek\">οἶκος</span>. SEG XXXVIII, 2032 (bibliografia).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιούσιος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιούσιος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">περί</span> + <span class=\"greek\">εἰμί</span>, <span class=\"greek\">περίειμι</span> «estar acima e além»), relativo a uma condição muito especial, escolhido, especial (PGen 11, 17, em que um homem casado é chamado <span class=\"greek\">ὁ</span> <span class=\"greek\">περιούσιος</span> «o escolhido»; Herm. Wr. 1, 19: Rtzst., Poim. 334; LXX). <span class=\"greek\">λαὸς</span> <span class=\"greek\">π</span>., tradução de <span class=\"hebrew\" dir=\"rtl\">עַם</span> <span class=\"hebrew\" dir=\"rtl\">סְגֻלָּה</span> Ex 19:5; 23:22 (aqui somente na LXX); Dt 7:6; 14:2 (<span class=\"greek\">λ</span>. <span class=\"greek\">π</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐθνῶν</span> ou <span class=\"greek\">παρὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span>); 26:18; seguindo esses exemplos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:14</a>; 1 Cl 64 «um povo escolhido» (B-D-F §113, 1; Mlt-H. 322; Lghtf., On a Fresh Revision of the Engl. NT 1891, 260ss.).—DELG s.v. <span class=\"greek\">εἰμί</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιοχή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιοχή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Theophr. e outros; Herm. Wr. 8, 5; papiros, LXX; Philo, Aet. M. 4; Jos., Bell. 5, 169; 203). <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">γραφῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:32</a> pode significar tanto ① conteúdo ou redação de um texto escrito, de uma Escritura (<span class=\"greek\">περιοχή</span> nesse sentido, escólio a Thu. 1, 131 <span class=\"greek\">ἡ</span> <span class=\"greek\">περ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">γραμμάτων</span>; escólio a Apollon. Rhod. 4, sobrescrito; cf. também Suda s.v. <span class=\"greek\">Ὅμηρος</span> <span class=\"greek\">Σέλλιος</span>) — quanto ② trecho de um texto escrito, de uma Escritura (Dionys. Hal., de Thu. c. 25; Cicero, Ad Attic. 13, 25, 3).—Blass sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:32</a>.—DELG s.v. 1 <span class=\"greek\">ἔχω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιπατέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιπατέω</span>, imperfeito <span class=\"greek\">περιεπάτουν</span>; futuro <span class=\"greek\">περιπατήσω</span>; 1.º aoristo <span class=\"greek\">περιεπάτησα</span> e <span class=\"greek\">ἐπεριπάτησα</span> ApcEsdr, veja 1a; mais-que-perfeito, 3.ª pessoa do singular <span class=\"greek\">περι</span>(<span class=\"greek\">ε</span>)<span class=\"greek\">πεπατήκει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:8</a>, variante textual (sobre o aumento no mais-que-perfeito, veja B-D-F §66, 1; Mlt.-H. 190s.) (Aristoph., X., Pla.+).<br>① Ir de um lugar a outro caminhando, circular, andar por aí.<br>ⓐ Com indicação do lugar por onde alguém anda (Demosth. 54, 7 <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀγορᾷ</span>; ApcEsdr 6:12 p. 31, 17 Tdf. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὄρει</span>; Jos., C. Ap. 2, 117 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>; Just., D. 1, 1 <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ξυστοῦ</span> <span class=\"greek\">περιπάτοις</span> «nas alamedas do Xystos»): <span class=\"greek\">ἐν</span> <span class=\"greek\">τριβόλοις</span> <span class=\"greek\">γυμνοῖς</span> <span class=\"greek\">ποσὶ</span> <span class=\"greek\">περιπατεῖν</span> «andar entre cardos com os pés descalços» Hs 9, 20, 3. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">γῇ</span> <span class=\"greek\">ταύτῃ</span> GJs 6:1. Em várias passagens seria possível traduzir «permanecer», «passar algum tempo», «estar», embora sem a ideia de ficar no mesmo lugar (Chion, Ep. 13, 1 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ὠιδείῳ</span>; 2 Km 11:2; Da 3:92, acerca dos homens na fornalha ardente; 4:29; En 17:6; Jos., Ant. 7, 130): <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἱερῷ</span> (Cebes 1, 1.—Diog. L. 4, 24 refere-se a Crantor caminhando pelo templo de Asclepius) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:23</a>; Ox 840, 9. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">Γαλιλαίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:1a</a>; cf. v. 1b. <span class=\"greek\">ὁ</span> <span class=\"greek\">περιπατῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μέσῳ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">λυχνιῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:1</a>. <span class=\"greek\">π</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">Ἰουδαίοις</span> «aparecer entre os judeus» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.54\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:54</a>.<br>ⓑ Circular, com indicação da roupa usada: <span class=\"greek\">ἐν</span> <span class=\"greek\">στολαῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:46</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">λευκοῖς</span> «vestido de branco» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:4</a> (Epict. 3, 22, 10 <span class=\"greek\">ἐν</span> <span class=\"greek\">κοκκίνοις</span> <span class=\"greek\">περιπ</span>.; Tat. 2:1 <span class=\"greek\">ἐν</span> <span class=\"greek\">πορφυρίδι</span> <span class=\"greek\">περιπατῶν</span>). <span class=\"greek\">ἐν</span> <span class=\"greek\">δέρμασιν</span> <span class=\"greek\">αἰγείοις</span> 1 Cl 17:1.<br>ⓒ Em geral, caminhar, ir: <span class=\"greek\">π</span>. <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φωτός</span> «andar na luz» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:24</a>. <span class=\"greek\">π</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀγρόν</span> «(ir) caminhar no campo» Hs 2:1. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλάσσης</span> (<span class=\"greek\">ἐπί</span> 1a e cf. Job 9:8.—GBertram, Le chemin sur les eaux: Congr. d’Hist. du Christ. I 1928, 137–66) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:48</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:19</a>. AcPl Ha 7, 27 e 34. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θάλασσαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:19</a> P75. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὕδατα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:29</a> (<span class=\"greek\">ἐπί</span> 4b<span class=\"greek\">β</span>). <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θάλασσαν</span> 4:18 (<span class=\"greek\">παρά</span> C1a). <span class=\"greek\">π</span>. <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> «andar com alguém» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.66\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:66</a>; «caminhar com alguém» Hs 9, 6, 2a; 9, 10, 1. <span class=\"greek\">π</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τι</span> «andar em volta de alguma coisa» Hs 9, 12, 7; também <span class=\"greek\">κύκλῳ</span> <span class=\"greek\">τινός</span> Hs 9, 6, 2b. <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> <span class=\"greek\">κύκλῳ</span> <span class=\"greek\">τινὸς</span> <span class=\"greek\">π</span>. «caminhar com alguém ao redor de alguma coisa» Hs 9, 11, 5. <span class=\"greek\">π</span>. <span class=\"greek\">ἐπάνω</span> «andar por cima» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:44</a> (<span class=\"greek\">ἐπάνω</span> 1a). Definido mais precisamente por <span class=\"greek\">ὁμαλῶς</span> <span class=\"greek\">π</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀπροσκόπως</span> Hm 6, 1, 4. <span class=\"greek\">γυμνὸν</span> <span class=\"greek\">π</span>. «andar nu» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:15</a>. <span class=\"greek\">μόνον</span> <span class=\"greek\">π</span>. «caminhar sozinho» Hv 4, 1, 3 (cf. Jos., C. Ap. 1, 281). <span class=\"greek\">περιεπάτεις</span> <span class=\"greek\">ὅπου</span> <span class=\"greek\">ἤθελες</span> «costumavas ir aonde querias» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:18</a> (En 17:6 <span class=\"greek\">ὅπου</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">σὰρξ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">περιπατεῖ</span>).—Em uso absoluto, andar, caminhar (Diocles 141 p. 180, 19s.; Diod S 1, 70, 10; EpArist 175; Just., D. 127, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:5</a>; 11:5; 15:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:9</a>; 5:42; 8:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:23</a>; 7:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:8</a>s., 11s.; 11:9s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:6</a>, 8ab, 9, 12; 14:8, 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:20</a> (cf. Ps 113:15); Hv 2, 1, 3; «(sair para) caminhar, estar passeando» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:17</a>; «passar caminhando» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:36</a>. <span class=\"greek\">περιπατῶν</span> <span class=\"greek\">ἀφύπνωσα</span> «enquanto caminhava, adormeci» Hv 1, 1, 3. <span class=\"greek\">περιπατῶν</span> <span class=\"greek\">ἀνεμνήσθην</span> «enquanto caminhava, lembrei-me» 2, 1, 1.<br>ⓓ Em imagens, já bastante próximo do emprego não literal da palavra: os que duvidam são <span class=\"greek\">περιπατοῦντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἀνοδίαις</span> Hv 3, 7, 1. Especialmente em João: <span class=\"greek\">περιπατεῖν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σκοτίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:12</a>; 12:35b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:11</a>; cf. 1:6. Em correspondência, <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">φωτί</span> v. 7; <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῇ</span> (=<span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδῷ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φωτός</span>) B 19:1 (mas também pode referir-se a <span class=\"greek\">ἡ</span> <span class=\"greek\">γνῶσις</span>; nesse caso a passagem pertenceria a 2a<span class=\"greek\">δ</span> abaixo). <span class=\"greek\">μέγα</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἀσεβείας</span> <span class=\"greek\">ὑπόδειγμα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμῳ</span> <span class=\"greek\">περιεπάτησεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰούδας</span> «Judas andou por este mundo como notável exemplo de impiedade» Papias (3:2). Uso absoluto: <span class=\"greek\">περιπατεῖτε</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">ἔχετε</span> «andai enquanto tendes a luz» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:35a</a>.<br>② Conduzir a própria vida, comportar-se, proceder, viver como hábito de conduta; extensão figurada de 1.<br>ⓐ Acerca do «modo de vida», andar, conduzir-se (Philod., <span class=\"greek\">Περὶ</span> <span class=\"greek\">παρρησίας</span> p. 12 Ol.; Epict. 1, 18, 20; veja Simplicius em Epict. p. 125, 52 Düb. Especialmente segundo modelos do Antigo Testamento (OT): 4 Km 20:3 <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀληθείᾳ</span>; Pr 8:20 <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁδοῖς</span> <span class=\"greek\">δικαιοσύνης</span>.—Eccl 11:9). No NT esse uso é decididamente paulino (as epístolas pastorais não empregam o termo); em outros lugares é relativamente frequente somente em 2J e 3J; «viver, conduzir-se, andar», sempre com determinação mais precisa:<br><span class=\"greek\">α</span>. Por um advérbio: <span class=\"greek\">ἀξίως</span> <span class=\"greek\">τινός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:12</a>; Pol 5:1. <span class=\"greek\">ἀτάκτως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:6</a>, 11. <span class=\"greek\">εὐσχημόνως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:12</a>.<br><span class=\"greek\">β</span>. Pelo dativo, indicando circunstância concomitante, natureza ou modo (TestIss 5:8 <span class=\"greek\">ἁπλότητι</span>.—B-D-F §198, 5; veja Rob. 528–32): <span class=\"greek\">κώμοις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μέθαις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:13</a>. <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔθεσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:21</a>; cf. 15:1 D; <span class=\"greek\">πνεύματι</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:16</a>. <span class=\"greek\">τῷ</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">πνεύματι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:18</a>.<br><span class=\"greek\">γ</span>. Por comparação: <span class=\"greek\">ἕκαστον</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">κέκληκεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>, <span class=\"greek\">οὕτως</span> <span class=\"greek\">περιπατείτω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:17</a>. <span class=\"greek\">περιπατεῖν</span> <span class=\"greek\">καθὼς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span> <span class=\"greek\">περιπατεῖ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:17</a>; <span class=\"greek\">ὡς</span> <span class=\"greek\">τέκνα</span> <span class=\"greek\">φωτός</span> 5:8.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:6</a>. A comparação está implícita no contexto (<span class=\"greek\">ὡς</span> <span class=\"greek\">ἐχθροὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:18</a>.—<span class=\"greek\">πῶς</span> (<span class=\"greek\">καθὼς</span>) <span class=\"greek\">περιπατεῖτε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:1a</a>b.<br><span class=\"greek\">δ</span>. Por expressão preposicional. A esfera em que alguém vive ou deve viver, de modo a ser caracterizado por ela, é designada por <span class=\"greek\">ἐν</span>: plural, «em pecados» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:7</a>; «em boas obras» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:10</a>; «nas ordenanças do Senhor» B 21:1 (Philo, Congr. Erud. Gr. 87 <span class=\"greek\">π</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">κρίσεσι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">προστάξεσιν</span>). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:9</a>. Singular: <span class=\"greek\">ἐν</span> <span class=\"greek\">καινότητι</span> <span class=\"greek\">ζωῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:4</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">πανουργίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:2</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀγάπῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:2</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">σοφίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:5</a>. <span class=\"greek\">ἐν</span> (<span class=\"greek\">τῇ</span>) <span class=\"greek\">ἀληθείᾳ</span> 2J 4; 3J 3s.; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀκεραιοσύνῃ</span> B 10:4; cf. B 19:1 (veja 1d acima). <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀλλοτρίᾳ</span> <span class=\"greek\">γνώμῃ</span> IPhld 3:3. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀμώμῳ</span> … <span class=\"greek\">συνειδήσει</span> Pol 5:3. <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῇ</span> (=<span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐντολῇ</span>) 2J 6b. <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> (=<span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:6</a>.—A norma de conduta é designada por <span class=\"greek\">κατὰ</span> com acusativo (veja <span class=\"greek\">κατά</span> B5b<span class=\"greek\">γ</span>): <span class=\"greek\">κατὰ</span> <span class=\"greek\">ἄνθρωπον</span> «como pessoas comuns (não regeneradas)» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:3</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> «segundo o antigo eu, a saber, a carne, em oposição ao novo eu sob o espírito» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:2</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">ἀγάπην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:15</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παράδοσιν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πρεσβυτέρων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:5</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐντολὰς</span> <span class=\"greek\">αὐτοῦ</span> 2J 6a.—BEaston, NT Ethical Lists: JBL 51, ’32, 1–12; SWibbing, D. Tugend-u. Lasterkataloge im NT, ’59; EKamlach, Die Form der katalogischen Paränese im NT, ’64; HBraun, Qumran u. das NT II, ’66, 286–301; JHolloway III, <span class=\"greek\">ΠΕΡΙΠΑΤΕΩ</span> as a Thematic Marker for Pauline Ethics ’92.<br>ⓑ Raramente, acerca da vida física em geral: <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">τῶ</span> <span class=\"greek\">κόσμῳ</span> <span class=\"greek\">περιπατεῖν</span> (formulação como em Papias [3:2]) B 10:11. <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:3</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">περιπατοῦμεν</span>, <span class=\"greek\">οὐ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">εἴδους</span> 5:7.—B. 690. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιπείρω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιπείρω</span>, 1.º aoristo <span class=\"greek\">περιέπειρα</span>, traspassar, empalar (literalmente em Diod S; Lucian; Plut., C. Gracch. 842 [17, 5] <span class=\"greek\">κεφαλὴ</span> <span class=\"greek\">περιπεπαρμένη</span> <span class=\"greek\">δόρατι</span>; Philo; Jos., Bell. 3, 296). Figuradamente, <span class=\"greek\">ἐαυτὸν</span> <span class=\"greek\">π</span>. <span class=\"greek\">ὀδύναις</span> <span class=\"greek\">πολλαῖς</span> «traspassar a si mesmo com muitas dores» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:10</a> (Philo, In Flacc. 1 <span class=\"greek\">ἀθρόους</span> <span class=\"greek\">ἀνηκέστοις</span> <span class=\"greek\">περιέπειρε</span> <span class=\"greek\">κακοῖς</span>.—Imagem semelhante em Pind., P. 2, 91 <span class=\"greek\">ἐνέπαξαν</span> <span class=\"greek\">ἕλκος</span> <span class=\"greek\">ὀδυναρὸν</span> <span class=\"greek\">ἑᾷ</span> <span class=\"greek\">πρόσθε</span> <span class=\"greek\">καρδίᾳ</span> = «cravar no próprio coração uma ferida dolorosa»).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περίπικρος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περίπικρος</span>, <span class=\"greek\">ον</span> (Philod., Ira [=<span class=\"greek\">Περὶ</span> <span class=\"greek\">ὀργῆ</span> PHercul. 182] p. 6 Wilke; Vi. Aesopi I G 38 P. e outros escritores posteriores), muito amargo, figuradamente, acerca de um olhar: <span class=\"greek\">βλέμμα</span> <span class=\"greek\">π</span>. «um olhar muito amargo» Hs 6, 2, 5.—DELG s.v. <span class=\"greek\">πικρός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιπίπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιπίπτω</span>, futuro, 2.ª pessoa do plural <span class=\"greek\">περιπεσεῖσθε</span> Da 2:9; 2.º aoristo <span class=\"greek\">περιέπεσον</span> (trágicos, Hdt.+), frequentemente com dativo, respondendo à pergunta «para onde?» (B-D-F §202; veja Rob. 528s.).<br>① Mover-se em direção a alguma coisa e chocar-se contra ela, atingir: <span class=\"greek\">εἰς</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">διθάλασσον</span> «atingir um ponto de terra» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:41</a> (quanto ao uso com <span class=\"greek\">εἰς</span>, cf. Oxy 3314, 7; veja também <span class=\"greek\">διθάλασσο</span>).<br>② Encontrar por acaso, deparar-se com, cair em.<br>ⓐ Acerca de pessoas hostis: <span class=\"greek\">λῃσταῖς</span> «cair entre salteadores» ou «nas mãos de salteadores» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:30</a> (Diod S 14, 93, 4 <span class=\"greek\">λῃσταῖς</span> <span class=\"greek\">περιέπεσον</span>; Conon [I a.C./I d.C.]: 26 Fgm. 1, 22 Jac. <span class=\"greek\">λῃσταῖς</span> <span class=\"greek\">περιπ</span>.; Diog. L. 4, 50 <span class=\"greek\">λῃσταῖς</span> <span class=\"greek\">περιέπεσε</span>; Artem. 3, 65; cf. 1, 5; 2, 22; Simplicius In Epict. p. 111, 13 Düb. <span class=\"greek\">δύο</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Δελφοὺς</span> <span class=\"greek\">ἀπιόντες</span> <span class=\"greek\">λῃσταῖς</span> <span class=\"greek\">περιπεπτώκασι</span>).<br>ⓑ Figuradamente, acerca de circunstâncias aflitivas (como frequentemente desde Hdt. 6, 106, 2; Thu. 8, 27, 3 <span class=\"greek\">κινδύνῳ</span>. Também em inscrições, papiros, LXX; TestDan 4:5; ApcMos 5 <span class=\"greek\">εἰς</span> <span class=\"greek\">νόσον</span>; Philo, Leg. All. 2, 77; Jos., Ant. 10, 25; 20, 48; Just., D. 32, 1 4:5 <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐσχάτῃ</span> <span class=\"greek\">κατάρᾳ</span>): <span class=\"greek\">πειρασμοῖς</span> <span class=\"greek\">ποικίλοις</span> «envolver-se em provações diversas» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:2</a>. <span class=\"greek\">αἰκίαις</span> <span class=\"greek\">π</span>. «sofrer torturas» 1 Cl 51:2 (Diod S 1, 74, 7 <span class=\"greek\">περιπίπτει</span> <span class=\"greek\">τιμωρίαις</span> = «incorre em castigo», literalmente «cai em castigo»).—M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιπλέκω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιπλέκω</span>, imperfeito <span class=\"greek\">περιέπλεκον</span> (Hom. e outros; LXX; TestSol 21:3 Q; JosAs 16:14 cód. A [p. 69, 4 Bat.]; Philo, Poster. Cai. 156), entretecer ou entrelaçar ao redor; figuradamente (escólio a Soph., Ant. 244 p. 230 Papag. <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span>), acerca de uma língua enganosa, <span class=\"greek\">περιέπλεκεν</span> <span class=\"greek\">δολιότητα</span> (veja <span class=\"greek\">δολιότης</span>) 1 Cl 35:8 (Ps 49:19).—Voz média: particípio do 2.º aoristo, acusativo plural <span class=\"greek\">περιπλακομένους</span> (TestAbr A 5 p. 82, 25 [Stone p. 12]). Passivo: 2.º aoristo <span class=\"greek\">περιεπλάκην</span>, LXX, particípio <span class=\"greek\">περιπλακείς</span>; particípio perfeito <span class=\"greek\">περιπεπλεγμένος</span> LXX. Em sentido ativo, abraçar, <span class=\"greek\">τινί</span> «alguém» (Hom. e outros; TestAbr A; Jos., Ant. 8, 7) Hs 9, 11, 4ab. <span class=\"greek\">περιπλακὶς</span> (=<span class=\"greek\">εὶ</span>) <span class=\"greek\">τῷ</span> <span class=\"greek\">Παύλῳ</span> AcPl Ha 8, 3 (cf. TestAbr A 15 p. 95, 16s. [Stone p. 38] <span class=\"greek\">περιεπλάκη</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τράχηλον</span> <span class=\"greek\">αὐτοῦ</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιποιέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιποιέω</span> (Hdt. e outros; inscrições, papiros, LXX; EpArist 121); em nossa literatura, apenas voz média (Thu. e outros; LXX; TestSol 9:2 P; Joseph.); futuro ativo, 2.ª pessoa do plural <span class=\"greek\">περιποιήσετε</span> Ex 22:17; infinitivo do 1.º aoristo <span class=\"greek\">περιποιῆσαι</span> 1 Macc 6:44, particípio dativo <span class=\"greek\">περιποιήσαντι</span> 2 Macc 3:35. Médio: futuro <span class=\"greek\">περιποιήσομαι</span>; 1.º aoristo <span class=\"greek\">περιεποιησάμην</span>; perfeito <span class=\"greek\">περιπεποίημαι</span> 1 Ch 29, 3. Sentido primário: «fazer permanecer além do necessário».<br>① Garantir segurança para si, salvar, preservar (para si), <span class=\"greek\">τί</span> «alguma coisa»: <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span> «preservar a própria vida» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:33</a> (cf. X., Cyr. 4, 4, 10 <span class=\"greek\">τὰς</span> <span class=\"greek\">ψυχάς</span> = «sua vida»).<br>② Obter a posse de alguma coisa, adquirir, obter, ganhar para si (Thu. 1, 9, 2; X., Mem. 2, 7, 3; Polyb. 3, 6, 13; 24, 9, 6; Is 43:21; Jos., Bell. 1, 180): <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰῶνα</span> <span class=\"greek\">τοῦτον</span> Hv 1, 1, 8. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐκκλησίαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <span class=\"greek\">ἣν</span> <span class=\"greek\">περιεποιήσατο</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἵματος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἰδίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:28</a> (veja Haenchen, AG, ad loc.; Danker, Benefactor, 335s.).—Frequentemente com acréscimo pleonástico de pronome reflexivo (X., An. 5, 6, 17 <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">δύναμιν</span> <span class=\"greek\">περιποιήσασθαι</span>; Demosth. 19, 240; PTor II, 8, 70 [119 a.C.]; Pr 7:4): <span class=\"greek\">βαθμὸν</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">καλὸν</span> <span class=\"greek\">περιποιοῦνται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:13</a>. Cf. <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">μέγα</span> <span class=\"greek\">κλέος</span> 1 Cl 54:3. <span class=\"greek\">σεαυτῷ</span> <span class=\"greek\">ζωήν</span> Hm 3:5. <span class=\"greek\">σεαυτῷ</span> <span class=\"greek\">δόξαν</span> <span class=\"greek\">περισσότεραν</span> Hs 5, 3, 3. <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">τιμήν</span> m 4, 4, 2. <span class=\"greek\">θάνατον</span> <span class=\"greek\">ἑαυτοῖς</span> Hs 6, 5, 7c. Também sem acusativo, facilmente subentendido, <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">π</span>. «enriquecer a si mesmos» Hs 9, 26, 2.<br>③ Produzir determinada circunstância, ocasionar, trazer alguma coisa para alguém, <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> (Aristot., Pol. 3, 16; PAmh. 34d, 2 [II a.C.] <span class=\"greek\">πλεῖόν</span> <span class=\"greek\">τι</span> <span class=\"greek\">περιποιούμενοι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">βασιλεῖ</span>; 2 Macc 15:21; Jos., Ant. 14, 386.—Mayser II/1, 1926 p. 101): <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">τρυφὴ</span> <span class=\"greek\">ζωὴν</span> <span class=\"greek\">περιποιεῖται</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀνθρώπῳ</span> Hs 6, 5, 7a. <span class=\"greek\">τιμωρίας</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">περιποιοῦνται</span> ibid. v. 7b.—M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιποίησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιποίησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">περιποιέω</span>; desde Ps.-Pla., Defin. 451c; PTebt 317, 26 [174/75 d.C.]; PRein 52, 2).<br>① Experiência de segurança, conservação em segurança, preservação, salvação (veja <span class=\"greek\">περιποιέω</span> 1; assim Ps.-Pla., loc. cit. <span class=\"greek\">σωτηρία</span>· <span class=\"greek\">π</span>. <span class=\"greek\">ἀβλαβής</span>; 2 Ch 14:12; TestZeb 2:8): <span class=\"greek\">εἰς</span> <span class=\"greek\">π</span>. <span class=\"greek\">ψυχῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.39\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:39</a> (em oposição a <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀπώλειαν</span>).<br>② Experiência de um acontecimento de aquisição, obtenção, conquista (<span class=\"greek\">περιποιέω</span> 2), seguido de genitivo objetivo (Alex. Aphr., An. Mant. p. 164, 17 Bruns [1887]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:14</a>.<br>③ Aquilo que é adquirido, aquilo que se possui, posse, propriedade (PTebt loc. cit.): <span class=\"greek\">λαὸς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">περιποίησιν</span> «um povo que se tornou propriedade (do próprio Deus)» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:9</a> (cf. Mal 3:17). <span class=\"greek\">ἀπολύτρωσις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:14</a> (veja <span class=\"greek\">ἀπολύτρωσις</span> 2a).—DELG s.v. <span class=\"greek\">ποιέω</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περίπτωσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περίπτωσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πτῶσις</span>; Stoic. II p. 29; Ammonius Gr. [100 d.C.] p. 60 Valck.: «desgraça»; M. Ant. 6, 41, 1 <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κακοῦ</span> e outros), experiência, neste caso desagradável, desgraça, calamidade (com <span class=\"greek\">συμφορά</span>) 1 Cl 1:1.—DELG s.v. <span class=\"greek\">πίπτω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περι(ρ)ραίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περι</span>(<span class=\"greek\">ρ</span>)<span class=\"greek\">ραίνω</span>, futuro, 3.ª pessoa do singular <span class=\"greek\">περιρρανεῖ</span> LXX. Passivo: particípio perfeito <span class=\"greek\">περιρεραμμένος</span> (sobre a reduplicação, veja Kühner-Bl. II p. 23; B-D-F §68; Rob. 211s.), neutro <span class=\"greek\">περιρεραμμένον</span> (Aristoph. e outros; inscrições; Lev; Num; Philo; Jos., Ant. 9, 123; 13, 243), aspergir ao redor, por todos os lados (Diogenes, o cínico, é da opinião [Diog. L. 6, 42] que, por mais extensa que seja a aspersão <span class=\"greek\">περι</span>(<span class=\"greek\">ρ</span>)<span class=\"greek\">ραίνειν</span>, é impossível livrar-se dos <span class=\"greek\">ἁμαρτήματα</span>): <span class=\"greek\">ἱμάτιον</span> <span class=\"greek\">περιρεραμμένον</span> <span class=\"greek\">αἵματι</span> «uma veste aspergida de sangue por todos os lados» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:13</a>, variante textual (em lugar de <span class=\"greek\">βεβαμμένον</span>; outras variantes textuais <span class=\"greek\">ῥεραντισμένον</span>, <span class=\"greek\">ἐρραμένον</span>).—DELG s.v. <span class=\"greek\">ῥαίνω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περι(ρ)ρήγνυμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περι</span>(<span class=\"greek\">ρ</span>)<span class=\"greek\">ρήγνυμι</span>, particípio do 1.º aoristo <span class=\"greek\">περιρήξας</span> (ou <span class=\"greek\">περιρρήξας</span>, veja B-D-F §11, 1), infinitivo <span class=\"greek\">περιρῆξαι</span> (TestJob 39:7) (Aeschyl. e outros), arrancar rasgando (por toda a volta), <span class=\"greek\">τὶ</span> «alguma coisa», especialmente roupas (Aeschyl., Sept. 329; Demosth. 19, 197 <span class=\"greek\">τὸν</span> <span class=\"greek\">χιτωνίσκον</span>; Polyb. 15, 33, 4; Diod S 17, 35, 7; 2 Macc 4:38 <span class=\"greek\">τοὺς</span> <span class=\"greek\">χιτῶνας</span>; Philo, De Jos. 16 [médio]; cf. Jos., Bell. 2, 601, Ant. 6, 357): <span class=\"greek\">περιρήξαντες</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱμάτια</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:22</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περισπάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περισπάω</span>, futuro, 3.ª pessoa do singular <span class=\"greek\">περισπάσει</span> (Just.); aoristo, 3.ª pessoa do singular <span class=\"greek\">περιέσπασε</span> 2 Km 6:6; imperfeito passivo, 3.ª pessoa do singular <span class=\"greek\">περιεσπᾶτο</span> (Eur., X. e outros; inscrições, papiros, LXX, Joseph.; Just., D. 2, 4; veja Phryn. p. 415 Lob.); em nossa literatura, somente voz passiva. O sentido primário («puxar para longe de algo que estava ao redor», Isoc., Ep. 9, 10) é perceptível no seguinte:<br>① Ser puxado para longe de um ponto de referência, ser arrastado para longe (a voz ativa em Polyb., Diod S, Dionys. Hal., Plut. e outros; a passiva em Cebes 33, 3; PTebt 124, 39 [I a.C.] <span class=\"greek\">εἰς</span> <span class=\"greek\">ἑτέρας</span> <span class=\"greek\">λειτουργίας</span>; Jos., Ant. 5, 46): <span class=\"greek\">περισπώμενος</span> <span class=\"greek\">ὧδε</span> <span class=\"greek\">κἀκεῖσε</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πνευμάτων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πονηρῶν</span> Hm 5, 2, 7 (sobre a construção com <span class=\"greek\">ἀπό</span>, cf. Epict. 1, 8, 5).<br>② Ter a atenção dirigida de uma coisa para outra, tornar-se ou estar distraído, muito ocupado, sobrecarregado (Polyb. 4, 10, 3; Diod S 2, 29, 5; Epict. 3, 9, 19; Jos., Bell. 1, 232 e outros; UPZ 59, 30 [168 a.C.]; PTebt 37, 15 [I a.C.]; POxy 743, 36 [I a.C.]), <span class=\"greek\">περί</span> <span class=\"greek\">τι</span> «com alguma coisa» ou «por alguma coisa» (Polyb. 3, 105, 1; Diod S 1, 74): <span class=\"greek\">περὶ</span> <span class=\"greek\">πολλὴν</span> <span class=\"greek\">διακονίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:40</a>. <span class=\"greek\">περὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πλοῦτον</span> Hs 2:5. <span class=\"greek\">περὶ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">πραγματείας</span> 4:5.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περισσεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περισσεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (veja o verbete seguinte; Herodian, Gr. I 291, 9 e outros; escólio a Nicander, Ther. 266), aquilo que excede a quantidade regular ou esperada, excesso, abundância (IG V/1, 550, 6 <span class=\"greek\">π</span>. <span class=\"greek\">χρημάτων</span>; VII, 3221, 5 [<span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span>] <span class=\"greek\">περισσήας</span>; inscrição da Síria: BCH 21, 1897 p. 65. Na LXX, apenas algumas vezes em Eccl.—Dssm., LO 66 [LAE 80]): <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">χάριτος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:17</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">χαρᾶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:2</a>. <span class=\"greek\">μεγαλυνθῆναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">π</span>. «ser grandemente ampliado» 10:15. <span class=\"greek\">π</span>. <span class=\"greek\">κακίας</span> «todo o mal que prevalece (ao vosso redor)» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:21</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. <span class=\"greek\">μου</span> «o excesso (das minhas ofertas)», isto é, Joachim ofereceu dádivas além das exigências cultuais em benefício do povo, GJs 1:1 (variante textual <span class=\"greek\">περιουσίας</span>).—DELG s.v. <span class=\"greek\">περί</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περίσσευμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περίσσευμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (veja o verbete anterior).<br>① Estado de grande fartura, abundância, plenitude (Eratosth. [III a.C.], Cat. 44 Olivieri; Plut., Mor. 310c; 962f.—A LXX de Eccl 2:15 apresenta a palavra na linha 6, mas essa linha falta no texto hebraico; por isso, provavelmente é acréscimo cristão: AMcNeile, An Introd. to Eccl 1904, 157; PKatz, TLZ 63, ’38, 34) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:14a</a>b (em oposição a <span class=\"greek\">ὑστέρημα</span>). <span class=\"greek\">ἐκ</span> (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">περισσεύματος</span> (<span class=\"greek\">τῆς</span>) <span class=\"greek\">καρδίας</span> «da abundância do coração», «daquilo de que o coração está cheio» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:45</a>.<br>② Aquilo que permanece além do necessário, o que sobra (Artem. 3, 52 «sobras»): <span class=\"greek\">περισσεύματα</span> <span class=\"greek\">κλασμάτων</span> «pedaços que sobraram» (aparentemente do número total de pedaços partidos durante a distribuição, e não restos deixados pelos comensais) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:8</a>.—DELG s.v. <span class=\"greek\">περί</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περισσεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περισσεύω</span>, imperfeito <span class=\"greek\">ἐπερίσσευον</span>; futuro <span class=\"greek\">περισσεύσω</span>; 1.º aoristo <span class=\"greek\">ἐπερίσσευσα</span> (sobre o aumento, B-D-F §69, 4; Mlt-H. 192). Passivo: 1.º futuro <span class=\"greek\">περισσευθήσομαι</span> (veja os dois verbetes anteriores; Hes., Thu. e outros; inscrições, papiros, LXX, Philo, Joseph.).<br>① Intransitivo, existir em abundância, abundar.<br>ⓐ Acerca de coisas:<br><span class=\"greek\">α</span>. Ser mais que suficiente, sobrar, restar (SIG 672, 19 [II a.C.]; Theophil.: 733 Fgm. 1 Jac. [em Alex. Polyhist.: Eus., PE 9, 34, 19]; Jos., Ant. 3, 229, Vi. 333): <span class=\"greek\">τὰ</span> <span class=\"greek\">περισσεύσαντα</span> <span class=\"greek\">κλάσματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:12</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">χρόνος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">περισσεύων</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παρουσίαν</span> <span class=\"greek\">αὐτοῦ</span> «o tempo que resta antes de sua vinda» Hs 5, 5, 3. <span class=\"greek\">οἱ</span> <span class=\"greek\">περισσεύοντες</span> «os outros, os restantes» 9, 8, 7; com genitivo, <span class=\"greek\">οἱ</span> <span class=\"greek\">π</span>. <span class=\"greek\">αὐτῶν</span> v. 4; forma reforçada <span class=\"greek\">οἱ</span> <span class=\"greek\">λοιποὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">περισσεύσαντες</span> 9, 9, 4. <span class=\"greek\">τὸ</span> <span class=\"greek\">περισσεῦον</span> «aquilo que sobrou», <span class=\"greek\">τῶν</span> <span class=\"greek\">κλασμάτων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:20</a>; 15:37 (cf. Jos., Ant. 13, 55). <span class=\"greek\">περισσεύει</span> <span class=\"greek\">μοί</span> <span class=\"greek\">τι</span> «deixo alguma coisa» (cf. Tob 4:16) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:13</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">περισσεῦσαν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">κλασμάτων</span> «o que deixaram em fragmentos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:17</a>.<br><span class=\"greek\">β</span>. Estar presente em abundância (X., Cyr. 6, 2, 30; PFlor 242, 2; PLond II, 418, 4 p. 303 [cerca de 346 d.C.] <span class=\"greek\">ἵνα</span> <span class=\"greek\">περισσεύῃ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">φόβος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σοί</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:5b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:26</a>. <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">περισσεύσῃ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">δικαιοσύνη</span> <span class=\"greek\">πλεῖον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">γραμματέων</span> «se vossa justiça não exceder amplamente a dos escribas» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:20</a> (sobre a omissão de «a dos» no texto grego, cf. Maximus Tyr. 15, 8d: a vida deles não difere em nada <span class=\"greek\">σκωλήκων</span> = «da» dos vermes). <span class=\"greek\">περισσεύει</span> <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> (cf. Thu. 2, 65, 13) «alguém tem alguma coisa em abundância» (Tob 4:16) ISm 9:2. <span class=\"greek\">τὸ</span> <span class=\"greek\">περισσεῦόν</span> <span class=\"greek\">τινι</span> (oposto a <span class=\"greek\">ὑστέρησις</span>) «a abundância de alguém» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:44</a>. (Oposto a <span class=\"greek\">ὑστέρημα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:4</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">περισσεύειν</span> <span class=\"greek\">τινί</span> «nisso, isto é, em ter abundância» 12:15. <span class=\"greek\">περισσεύει</span> <span class=\"greek\">τι</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span> «alguma coisa chega a alguém ou fica à sua disposição em grande abundância»: <span class=\"greek\">ἡ</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πολλοὺς</span> <span class=\"greek\">ἐπερίσσευσεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:15</a>. <span class=\"greek\">περισσεύει</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">παθήματα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἡμᾶς</span> «participamos abundantemente dos sofrimentos de Cristo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:5a</a>.<br><span class=\"greek\">γ</span>. Ser extremamente rico ou abundante, transbordar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:12</a>. <span class=\"greek\">εἰ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀλήθεια</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐμῷ</span> <span class=\"greek\">ψεύσματι</span> <span class=\"greek\">ἐπερίσσευσεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">δόξαν</span> <span class=\"greek\">αὐτου</span> «se, por meio da minha mentira, a veracidade de Deus se manifestou supremamente grande para sua glória» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:7</a>. A coisa de que consiste essa riqueza é acrescentada no dativo (Philistion [IV a.C.], Fgm. 9 linha 13 Wellmann <span class=\"greek\">πάσαις</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀρεταῖς</span> <span class=\"greek\">περιττεύει</span> [em Athen. 3, 83, 115e]): <span class=\"greek\">π</span>. <span class=\"greek\">δόξῃ</span> «ser extremamente rico em glória» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:9</a> (variante textual <span class=\"greek\">ἐν</span> <span class=\"greek\">δόξῃ</span>). Em oxímoro, <span class=\"greek\">ἡ</span> <span class=\"greek\">πτωχεία</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἐπερίσσευσεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλοῦτος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἁπλότητος</span> <span class=\"greek\">αὐτῶν</span> «sua pobreza transbordou na riqueza de sua sinceridade» 8:2 (veja <span class=\"greek\">ἁπλότη</span> 1; NRSV e outros: «generosidade»).<br><span class=\"greek\">δ</span>. Crescer: <span class=\"greek\">αἱ</span> <span class=\"greek\">ἐκκλησίαι</span> <span class=\"greek\">ἐπερίσσευον</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀριθμῷ</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἡμέραν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:5</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀγάπη</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">περισσεύῃ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐπιγνώσει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:9</a>.<br>ⓑ Acerca de pessoas:<br><span class=\"greek\">α</span>. Ter abundância, abundar, ser rico, <span class=\"greek\">τινός</span> «de ou em alguma coisa» (B-D-F §172; Rob. 510): <span class=\"greek\">ἄρτων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:17</a>, variante textual (o texto tem o médio <span class=\"greek\">περισσεύονται</span> [a menos que seja considerado passivo, veja 2b abaixo], mas provavelmente não é original; veja Jülicher, Gleichn. 346). <span class=\"greek\">παντὸς</span> <span class=\"greek\">χαρίσματος</span> IPol 2:2. Também <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> Dg 5:13 (em oposição a <span class=\"greek\">ὑστερεῖσθαι</span>). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐλπίδι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:13</a>. Uso absoluto (oposto a <span class=\"greek\">ὑστερεῖσθαι</span>): <span class=\"greek\">περισσεύομεν</span> «temos mais (aprovação divina)» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:8</a>. <span class=\"greek\">ζητεῖτε</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">περισσεύητε</span> «procurai sobressair» 14:12. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:12a</a> (oposto a <span class=\"greek\">ταπεινοῦσθαι</span>), v. 12b (oposto a <span class=\"greek\">ὑστερεῖσθαι</span>). <span class=\"greek\">ἀπέχω</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">περισσεύω</span> «recebi o pagamento integral e tenho mais do que suficiente» v. 18. <span class=\"greek\">π</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">ἔργον</span> «ter recursos abundantes para toda atividade» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:8b</a>.<br><span class=\"greek\">β</span>. Ser destacado, notável, sobressair (1 Macc 3:30), <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> «em alguma coisa»: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἔργῳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.58\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:58</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:7a</a>b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:7</a>. Uso absoluto, com <span class=\"greek\">μᾶλλον</span> acrescentado: «progredir cada vez mais» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:1</a>, 10.<br>② Transitivo (Athen. 2, 42b), fazer algo existir em abundância, fazer abundar.<br>ⓐ Acerca de coisas que alguém aumenta grandemente: <span class=\"greek\">τὴν</span> <span class=\"greek\">εὐχαριστίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:15</a>. <span class=\"greek\">τὶ</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span> «conceder alguma coisa abundantemente a alguém» 9:8a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:8</a> (<span class=\"greek\">ἧς</span> por atração do relativo em lugar de <span class=\"greek\">ἥν</span>). Passivo com dativo de pessoa: <span class=\"greek\">ὅστις</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἔχει</span>, <span class=\"greek\">δοθήσεται</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">περισσευθήσεται</span> «àquele que tem, mais será dado, e essa pessoa terá grande abundância» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:12</a>. Cf. 25:29.<br>ⓑ Acerca de pessoas que recebem alguma coisa em grande abundância: <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">περισσεύσαι</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀγάπῃ</span> «que o Senhor vos faça abundar em amor» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:12</a>. <span class=\"greek\">πόσοι</span> <span class=\"greek\">μίσθιοι</span> <span class=\"greek\">περισσεύονται</span> <span class=\"greek\">ἄρτων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:17</a> «quantos trabalhadores diaristas recebem pão mais que suficiente» (veja 1b<span class=\"greek\">α</span> acima).—DELG s.v. <span class=\"greek\">περί</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περισσός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περισσός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (cf. <span class=\"greek\">πέριξ</span> e veja os três verbetes seguintes; Hes., Hdt.+. Primariamente, «que excede o número ou tamanho habitual»; Gignac I 146).<br>① Relativo àquilo que não se encontra normalmente, extraordinário, notável (Pla., Apol. 20c <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἄλλων</span> <span class=\"greek\">περισσὸν</span> <span class=\"greek\">πραγματεύεσθαι</span>; BGU 417, 22 <span class=\"greek\">περισσὸν</span> <span class=\"greek\">ποιήσω</span> = «vou fazer alguma coisa extraordinária»; En 102:7): <span class=\"greek\">τί</span> <span class=\"greek\">περισσὸν</span> <span class=\"greek\">ποιεῖτε</span>; «que fazeis de notável?» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:47</a> (cf. Plut., Mor. 233a <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">μέγα</span> <span class=\"greek\">ποιεῖς</span>; «que fazes, então, de tão grandioso?»—ELombard, L’Ordinaire et l’Extraordinaire [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:47</a>]: RTP 15, 1927, 169–86). Substantivado, <span class=\"greek\">τὸ</span> <span class=\"greek\">περισσόν</span> «a vantagem» (WSchubart, Der Gnomon des Idios Logos 1919, 102 [II d.C.]): <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰουδαίου</span> «a vantagem do judeu» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:1</a> (veja <span class=\"greek\">Ἰουδαῖο</span> 2a). LCerfaux, Le privilège d’Israël sel. s. Paul: ETL 17, ’40, 5–26.<br>② Relativo à quantidade excepcional, abundante, copioso.<br>ⓐ Que vai além do necessário: <span class=\"greek\">περισσὸν</span> <span class=\"greek\">ἔχειν</span> «ter (algo) em abundância» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:10</a> (cf. X., Oec. 20, 1 <span class=\"greek\">οἱ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">περισσὰ</span> <span class=\"greek\">ἔχουσιν</span>, <span class=\"greek\">οἱ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀναγκαῖα</span> <span class=\"greek\">δύνανται</span> <span class=\"greek\">πορίζεσθαι</span>; Plut., Mor. 523d). Para <span class=\"greek\">περισσότερον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:10</a> P75, veja <span class=\"greek\">περισσότερο</span> c.<br>ⓑ Supérfluo, desnecessário (trágicos e outros; cf. 2 Macc 12:44; TestJob 47:1): <span class=\"greek\">περισσόν</span> <span class=\"greek\">μοί</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">γράφειν</span> <span class=\"greek\">ὑμῖν</span> «é desnecessário que eu vos escreva» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:1</a> (Mitt-Wilck. I/2, 238 II, 4 <span class=\"greek\">περισσὸν</span> <span class=\"greek\">ἡγοῦμαι</span> <span class=\"greek\">διεξοδέστερον</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">γράφειν</span>). <span class=\"greek\">περισσὸν</span> <span class=\"greek\">ἡγοῦμαι</span> «considero supérfluo» (Appian, Prooem. 13 §50; Jos., Ant. 3, 215; cf. Philo, Agr. 59) Dg 2:10. Com <span class=\"greek\">ἄχρηστος</span> 4:2.<br>③ Em sentido comparativo; <span class=\"greek\">περισσός</span>, juntamente com seu advérbio e comparativo, substitui coloquialmente <span class=\"greek\">μᾶλλον</span>, <span class=\"greek\">μάλιστα</span>, bem como <span class=\"greek\">πλείων</span>, <span class=\"greek\">πλεῖστος</span> (B-D-F §60, 3; Rob. 279; KKrumbacher, ByzZ 17, 1908, 233): <span class=\"greek\">τό</span> <span class=\"greek\">περισσὸν</span> <span class=\"greek\">τούτων</span> «tudo o que for além disso», «o que exceder isso» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:37</a> (sobre o genitivo, veja B-D-F §185, 1; Rob. 660).—<span class=\"greek\">ἐκ</span> <span class=\"greek\">περισσοῦ</span> (<span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 34, 2; Vi. Aesopi I G 43 P.; Dositheus 40, 4; Da 3:22 Theod.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:51</a>, veja <span class=\"greek\">ἐκ</span> 6c e <span class=\"greek\">λίαν</span> a.—DELG s.v. <span class=\"greek\">περί</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0283-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περισσότερος, τέρα, ον</h1><div class=\"entry-meta\"><span>adjetivo comparativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περισσότερος</span>, <span class=\"greek\">τέρα</span>, <span class=\"greek\">ον</span>, comparativo de <span class=\"greek\">περισσός</span> (veja o verbete anterior; desde Hdt.; Pla., Apol. 20c <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἄλλων</span> <span class=\"greek\">περιττότερον</span> <span class=\"greek\">πραγματεύεσθαι</span>; PFlor 127, 22; TestAbr B 8 p. 113, 11 [Stone p. 74]; Da 4:36 Theod. <span class=\"greek\">μεγαλωσύνη</span> <span class=\"greek\">περισσοτέρα</span>), relativo a exceder um padrão de abundância, maior, mais, ainda mais.<br>ⓐ Empregado com substantivo: <span class=\"greek\">ἀγαθά</span> 1 Cl 61:3 (veja <span class=\"greek\">ἀγαθός</span> 1b<span class=\"greek\">α</span>). <span class=\"greek\">τιμή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:23a</a>, 24; Hm 4, 4, 2. <span class=\"greek\">δόξα</span> Hs 5, 3, 3. <span class=\"greek\">κρίμα</span> «punição mais severa» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:13</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:47</a>. <span class=\"greek\">εὐσχημοσύνη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:23b</a>. <span class=\"greek\">λύπη</span> «tristeza excessiva» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:7</a>.<br>ⓑ Com ênfase no aspecto incremental: <span class=\"greek\">περισσότερον</span> «ainda mais» (= mais do que o <span class=\"greek\">πολύ</span> que lhe fora confiado) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:48</a>. Com genitivo de comparação, <span class=\"greek\">περισσότερον</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἐκοπίασα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:10</a>.—<span class=\"greek\">περισσότερόν</span> <span class=\"greek\">τί</span> «algo mais ou adicional» (Lucian, Tyrannic. 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:4</a> (sobre isso, veja KKöhler, ZNW 18, 1918, 140s.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:8</a>. Com genitivo de comparação (Jos., Ant. 5, 23; 8, 410), <span class=\"greek\">περισσότερόν</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὁλοκαυτωμάτων</span> «é muito mais do que todos os holocaustos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:33</a>. <span class=\"greek\">περισσότερον</span> <span class=\"greek\">προφήτου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:26</a> pode ser entendido como neutro, «algo maior do que um profeta». Mas também pode ser entendido como masculino, «alguém que é mais do que um profeta» (cf. Plut., Mor. 57f <span class=\"greek\">περιττότερος</span> <span class=\"greek\">φρονήσει</span>; Gen 49:3 Sym. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔσῃ</span> <span class=\"greek\">περισσότερος</span>).<br>ⓒ Neutro singular usado como advérbio (Hdt. 2, 129 e outros; Vett. Val. p. 74, 6; PFlor 127, 22; BGU 380, 10; PGM 13, 12): <span class=\"greek\">ζωὴν</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἔχωσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:10</a> P75. <span class=\"greek\">π</span>. <span class=\"greek\">ἐπιδεῖξαι</span> «demonstrar ainda mais claramente» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:17</a>. <span class=\"greek\">π</span>. <span class=\"greek\">ἔτι</span> <span class=\"greek\">κατάδηλόν</span> <span class=\"greek\">ἐστιν</span> «é ainda mais evidente» 7:15. Em forma intensificada, «muito mais» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:36</a>.—B. 924. DELG s.v. <span class=\"greek\">περί</span>. M-M s.v. <span class=\"greek\">περισσός</span>.</p></section></article>"};
